# Expected Python solution for reference
def solve_py(A, C, M):
    if A > MAX_INPUT or C > MAX_INPUT or M > MAX_INPUT or (A+C+M) > MAX_INPUT:
        return 0
    N = A + C + M
    if N == 0:
        return 0
    # dp[a][c][m][prev]
    dp = [[[[0]*3 for _ in range(M+1)] for _ in range(C+1)] for _ in range(A+1)]
    if A > 0:
        dp[1][0][0][0] = 1
    if C > 0:
        dp[0][1][0][1] = 1
    if M > 0:
        dp[0][0][1][2] = 1

    for a in range(A+1):
        for c in range(C+1):
            for m in range(M+1):
                for prev in range(3):
                    cur = dp[a][c][m][prev]
                    if cur == 0:
                        continue
                    # Try add apple
                    if prev != 0 and a < A:
                        dp[a+1][c][m][0] = (dp[a+1][c][m][0] + cur) % MOD
                    # Try add cherry
                    if prev != 1 and c < C:
                        dp[a][c+1][m][1] = (dp[a][c+1][m][1] + cur) % MOD
                    # Try add mango
                    if prev != 2 and m < M:
                        dp[a][c][m+1][2] = (dp[a][c][m+1][2] + cur) % MOD

    total = 0
    for prev in range(3):
        total = (total + dp[A][C][M][prev]) % MOD
    return total

