import cocotb
from cocotb.triggers import Timer, RisingEdge
from cocotb.clock import Clock
from cocotb.result import TestFailure

# Constants
DATA_WIDTH = 5
INDEX_WIDTH = 4
ARRAY_SIZE = 16
CLK_NS = 10
MAX_CYCLES = 500
MOD = 1000000007

# Helper functions
def is_value_defined(v):
    try:
        int(v)
        return True
    except ValueError:
        return False

def safe_int(v, default=0):
    try:
        return int(v)
    except ValueError:
        return default

def clamp_to_width(v, bits):
    return min((1 << bits) - 1, max(0, v))

def has_signal(dut, name):
    try:
        getattr(dut, name)
        return True
    except AttributeError:
        return False

def compute_expected(t_vals):
    """Compute expected count in Python"""
    n = len(t_vals)
    t = [x - 1 for x in t_vals]  # 0-indexed
    visited = [False] * n
    even_cycles = 0

    for i in range(n):
        if not visited[i]:
            # Find cycle length
            j = i
            cycle_len = 0
            while not visited[j]:
                visited[j] = True
                j = t[j]
                cycle_len += 1

            if cycle_len % 2 == 0:
                even_cycles += 1

    # Result is 2^(even_cycles) % MOD
    result = pow(2, even_cycles, MOD)
    return result

async def reset_dut(dut):
    dut.rst_n.value = 0
    if has_signal(dut, 'start'):
        dut.start.value = 0
    if has_signal(dut, 't_valid'):
        dut.t_valid.value = 0

    # Wait 2 cycles
    for _ in range(2):
        if has_signal(dut, 'clk'):
            await RisingEdge(dut.clk)
        else:
            await Timer(CLK_NS * 2, units='ns')

    dut.rst_n.value = 1
    if has_signal(dut, 'clk'):
        await RisingEdge(dut.clk)
    else:
        await Timer(CLK_NS, units='ns')

async def wait_for_done(dut, max_cycles=MAX_CYCLES):
    for _ in range(max_cycles):
        if has_signal(dut, 'clk'):
            await RisingEdge(dut.clk)
        else:
            await Timer(CLK_NS, units='ns')

        if has_signal(dut, 'done') and is_value_defined(dut.done.value):
            if int(dut.done.value) == 1:
                return True
    return False

