    """Test TFD count (square root of permutation counting)"""

    # Setup clock
    if has_signal(dut, 'clk'):
        cocotb.start_soon(Clock(dut.clk, CLK_NS, units='ns').start())
        # Wait for a few cycles to stabilize
        for _ in range(3):
