MAX_CYCLES = 100000

# --- Helper: Rotate 180 logic in Python for verification ---
def is_rot180_symmetric(grid, r, c, size):
    for i in range(size):
        for j in range(size):
            val1 = grid[r + i][c + j]
            val2 = grid[r + size - 1 - i][c + size - 1 - j]
            if val1 != val2:
                return False
    return True

def find_max_size_python(grid, R, C):
    for s in range(min(R, C), 1, -1):
        for r in range(R - s + 1):
            for c in range(C - s + 1):
                if is_rot180_symmetric(grid, r, c, s):
                    return s
    return -1

# --- Helper: Pack matrix ---
def pack_matrix(grid, R, C):
    packed = 0
    for r in range(R):
        for c in range(C):
            if grid[r][c] == '1':
                packed |= (1 << (r * C + c))
    return packed

@cocotb.test(timeout_time=2000, timeout_unit="ms")
async def test_square_killer(dut):
    # Setup Clock
    if has_signal(dut, 'clk'):
        cocotb.start_soon(Clock(dut.clk, CLK_NS, units='ns').start())
    else:
        raise TestFailure("Module requires a 'clk' signal")

    # Reset
    if has_signal(dut, 'rst_n'):
        dut.rst_n.value = 0
        if has_signal(dut, 'start'): dut.start.value = 0
        for _ in range(2): await RisingEdge(dut.clk)
        dut.rst_n.value = 1
    else:
        # If no reset, ensure clean start
        for _ in range(2): await RisingEdge(dut.clk)

    await RisingEdge(dut.clk)

    # --- Test Cases ---
    # Format: (R, C, Matrix Strings, Expected Size)
    test_cases = [
        (3, 6, 
         ["101010", "111001", "101001"], 
         3),
        (4, 5, 
         ["10010", "01010", "10101", "01001"], 
         3),
        (3, 3, 
         ["101", "111", "100"], 
         -1),
        (2, 2, 
         ["11", "11"], 
         2),
        (2, 2, 
         ["10", "01"], 
         2), # Rotated is same
        (1, 5, 
         ["10101"], 
         -1) # Size 1 is not allowed (>1)
    ]

    passed = 0
    failed = 0

    for idx, (R, C, matrix_strs, expected) in enumerate(test_cases):
        cocotb.log.info(f"Running Test Case {idx+1}: R={R}, C={C}, Expected={expected}")

        # Prepare Input
        grid = [list(row) for row in matrix_strs]
        packed_val = pack_matrix(grid, R, C)

        # Drive Inputs
        if has_signal(dut, 'matrix_in'):
            dut.matrix_in.value = packed_val
        else:
            # Check for individual row/col inputs if matrix_in is not found
            # This is a fallback, though 'matrix_in' is specified in prompt
            pass

        if has_signal(dut, 'R'):
            dut.R.value = R
        if has_signal(dut, 'C'):
            dut.C.value = C

        # Start
        if has_signal(dut, 'start'):
            dut.start.value = 1
            await RisingEdge(dut.clk)
            dut.start.value = 0
        else:
             await RisingEdge(dut.clk)

        # Wait for Done
        found_done = False
        for _ in range(MAX_CYCLES):
            await RisingEdge(dut.clk)
            if has_signal(dut, 'done') and is_value_defined(dut.done.value) and int(dut.done.value) == 1:
                found_done = True
                break

        if not found_done:
            cocotb.log.error(f"Test {idx+1} FAILED: Timeout waiting for done signal")
            failed += 1
            continue

        # Read Result
        if not has_signal(dut, 'result'):
            cocotb.log.error("Test FAILED: 'result' signal not found")
            failed += 1
            continue

        result = int(dut.result.value)

        # Python verification for logging
        python_res = find_max_size_python(grid, R, C)
        if python_res != expected:
            cocotb.log.warning(f"Internal Python check mismatch: {python_res} vs Expected {expected}. Check test case definition.")

        if result == expected:
            cocotb.log.info(f"Test {idx+1} PASSED: Result {result}")
            passed += 1
        else:
            cocotb.log.error(f"Test {idx+1} FAILED: Expected {expected}, got {result}")
            failed += 1

    if failed > 0:
        raise TestFailure(f"{failed} tests failed")

import cocotb
from cocotb.triggers import Timer, RisingEdge
from cocotb.clock import Clock
from cocotb.result import TestFailure

# Helpers

def is_value_defined(v):
    try: int(v); return True
    except ValueError: return False

def safe_int(v, default=0):
    try: return int(v)
    except ValueError: return default

def clamp_to_width(v, bits):
    return min((1 << bits) - 1, max(0, int(v)))

def has_signal(dut, name):
    try: getattr(dut, name); return True
    except AttributeError: return False

async def reset_dut(dut, cycles=2):
    dut.rst_n.value = 0
    if has_signal(dut, 'start'): dut.start.value = 0
    for _ in range(cycles): await RisingEdge(dut.clk)
    dut.rst_n.value = 1
    await RisingEdge(dut.clk)

async def wait_for_done(dut, max_cycles=2048):
    for _ in range(max_cycles):
        await RisingEdge(dut.clk)
        if is_value_defined(dut.done.value) and int(dut.done.value) == 1:
            return True
    raise TestFailure(f"Timeout after {max_cycles} cycles")

DATA_WIDTH, CLK_NS, MAX_CYCLES = 32, 10, 2048

@cocotb.test(timeout_time=5000, timeout_unit="ms")
async def test_jeopardy_ai(dut):
    if has_signal(dut, 'clk'):
        cocotb.start_soon(Clock(dut.clk, CLK_NS, units='ns').start())
        await reset_dut(dut)

    test_cases = [
        (10, 5, 2, "Small case"),
        (2020, 2020, 1, "Large n"),
        (1, 0, 0, "Base case X=1"),
        (2, 2, 1, "X=2"),
        (6, 4, 2, "X=6"),
        (35, 7, 3, "X=35"),
    ]

    passed = 0
    failed = 0

    for i, (X, exp_n, exp_k, desc) in enumerate(test_cases):
        cocotb.log.info(f"Test {i+1}: {desc} (X={X})")
        try:
            # Set inputs
            if has_signal(dut, 'X'):
                dut.X.value = clamp_to_width(X, DATA_WIDTH)

            if has_signal(dut, 'start'):
                dut.start.value = 1
                await RisingEdge(dut.clk)
                dut.start.value = 0
                await wait_for_done(dut)
            else:
                # Combinational module
                await Timer(100, units='ns')

            # Check results
            if not is_value_defined(dut.done.value):
                raise TestFailure("Done signal undefined")

            if not has_signal(dut, 'valid') or not is_value_defined(dut.valid.value):
                raise TestFailure("Valid signal undefined")

            valid = int(dut.valid.value)
            if valid == 0:
                raise TestFailure(f"Valid is 0 for X={X}")

            result_n = int(dut.n.value)
            result_k = int(dut.k.value)

            if result_n != exp_n or result_k != exp_k:
                raise TestFailure(f"Expected ({exp_n}, {exp_k}), got ({result_n}, {result_k})")

            passed += 1
        except TestFailure as e:
            cocotb.log.error(f"FAIL: {e}")
            failed += 1

    # Test invalid case (X too large, > C(64,32) ≈ 1.8e18)
    # Using scaled X = 2^32-1 which is still valid, but to test invalid
    # we need a value larger than max C. Since we scale to 32-bit,
    # we test with X=0 (invalid) and expect valid=0
    cocotb.log.info("Test Invalid: X=0")
    try:
        if has_signal(dut, 'X'):
            dut.X.value = 0
        if has_signal(dut, 'start'):
            dut.start.value = 1
            await RisingEdge(dut.clk)
            dut.start.value = 0
            await wait_for_done(dut)
        else:
            await Timer(100, units='ns')

        if has_signal(dut, 'valid') and is_value_defined(dut.valid.value):
            valid = int(dut.valid.value)
            if valid != 0:
                raise TestFailure(f"Expected valid=0 for X=0, got valid={valid}")
        passed += 1
    except TestFailure as e:
        cocotb.log.error(f"FAIL: {e}")
        failed += 1

    if failed:
        raise TestFailure(f"{failed} tests failed")

import cocotb
from cocotb.triggers import Timer, RisingEdge
from cocotb.clock import Clock
from cocotb.result import TestFailure
import random

# Helpers
def is_value_defined(v):
    try: int(v); return True
    except ValueError: return False

def safe_int(v, default=0):
    try: return int(v)
    except ValueError: return default

def to_signed(val, bits):
    return val - (1 << bits) if val >= (1 << (bits-1)) else val

def from_signed(val, bits):
    return val + (1 << bits) if val < 0 else val

def has_signal(dut, name):
    try: getattr(dut, name); return True
    except AttributeError: return False

def clamp_to_width(v, bits):
    return min((1 << bits) - 1, max(0, v))

def write_shelf(dut, shelf_idx, arr, width, prefix='init'):
    """Write a single shelf's array to HDL"""
    for i, v in enumerate(arr):
        signal_name = f"{prefix}_arr_{shelf_idx}_{i}"
        if hasattr(dut, signal_name):
            getattr(dut, signal_name).value = clamp_to_width(v, width)

def pack_shelf(arr, width=8):
    """Pack shelf array into a single integer for combinational access if needed"""
    result = 0
    for i, v in enumerate(arr):
        result |= (v & ((1 << width) - 1)) << (i * width)
    return result

@cocotb.test(timeout_time=1000, timeout_unit="ms")
async def test_librarian(dut):
    # Parameters
    CLK_NS = 10
    MAX_SHELVES = 16
    MAX_SLOTS = 16
    DATA_WIDTH = 8

    # Check if sequential
    is_seq = has_signal(dut, 'clk')

    if is_seq:
        cocotb.start_soon(Clock(dut.clk, CLK_NS, units='ns').start())
        # Reset
        dut.rst_n.value = 0
        if has_signal(dut, 'start'): dut.start.value = 0
        for _ in range(2):
            await RisingEdge(dut.clk)
        dut.rst_n.value = 1
        await RisingEdge(dut.clk)

    # Test cases: (init, target, expected_lifts, is_impossible)
    # Using scaled versions of examples
    test_cases = [
        (
            [
                [1, 0, 2, 0],
                [3, 5, 4, 0]
            ],
            [
                [2, 1, 0, 0],
                [3, 0, 4, 5]
            ],
            2, False  # Example 1: books 1,2,4,5 need moves? Actually check logic
        ),
        (
            [
                [1, 2, 3, 0],
                [4, 5, 6, 0],
                [7, 8, 0, 0]
            ],
            [
                [4, 2, 3, 0],
                [6, 5, 1, 0],
                [0, 7, 8, 0]
            ],
            4, False  # Example 2
        ),
        (
            [
                [1, 2, 0, 0],
                [3, 4, 0, 0]
            ],
            [
                [2, 3, 0, 0],
                [4, 1, 0, 0]
            ],
            4, False  # Example 3 (impossible? But logic says 4 lifts)
        )
    ]

    passed = 0
    failed = 0

    for t_idx, (init, target, expected, impossible) in enumerate(test_cases):
        cocotb.log.info(f"Test {t_idx+1}")

        # Scale to 16 shelves, 16 slots
        N = len(init)
        M = len(init[0]) if N > 0 else 0

        # Pad arrays to 16x16
        init_full = [[0]*16 for _ in range(16)]
        target_full = [[0]*16 for _ in range(16)]
        for i in range(N):
            for j in range(M):
                init_full[i][j] = init[i][j]
                target_full[i][j] = target[i][j]

        # Write inputs
        dut.N.value = N
        dut.M.value = M

        for i in range(16):
            for j in range(16):
                # Init array
                init_sig_name = f"init_arr_{i}_{j}"
                if hasattr(dut, init_sig_name):
                    getattr(dut, init_sig_name).value = clamp_to_width(init_full[i][j], DATA_WIDTH)

                # Target array
                target_sig_name = f"target_arr_{i}_{j}"
                if hasattr(dut, target_sig_name):
                    getattr(dut, target_sig_name).value = clamp_to_width(target_full[i][j], DATA_WIDTH)

        # Compute expected logically for comparison
        # Count total books in init
        total_books = 0
        correct_books = 0
        books_in_init = set()
        books_in_target = set()

        for i in range(N):
            for j in range(M):
                val_init = init[i][j]
                val_target = target[i][j]
                if val_init != 0:
                    total_books += 1
                    books_in_init.add(val_init)
                if val_target != 0:
                    books_in_target.add(val_target)
                if val_init != 0 and val_init == val_target:
                    correct_books += 1

        if books_in_init != books_in_target:
            # Impossible
            expected = -1
            is_impossible = True
        else:
            is_impossible = False
            expected = total_books - correct_books

        if is_seq:
            # Pulse start
            if has_signal(dut, 'start'):
                dut.start.value = 1
                await RisingEdge(dut.clk)
                dut.start.value = 0
            else:
                # If no start, assume combinational or wait
                await Timer(100, units='ns')

            # Wait for done if exists
            if has_signal(dut, 'done'):
                done_found = False
                for _ in range(1000):
                    await RisingEdge(dut.clk)
                    if is_value_defined(dut.done.value) and int(dut.done.value) == 1:
                        done_found = True
                        break
                if not done_found:
                    cocotb.log.error(f"Test {t_idx+1}: Timeout waiting for done")
                    failed += 1
                    continue
            else:
                await Timer(100, units='ns')
        else:
            # Combinational
            await Timer(100, units='ns')

        # Read result
        result = 0
        error = 0

        if has_signal(dut, 'result'):
            if is_value_defined(dut.result.value):
                result = int(dut.result.value)
            else:
                cocotb.log.error(f"Test {t_idx+1}: Result undefined")
                failed += 1
                continue

        if has_signal(dut, 'error'):
            if is_value_defined(dut.error.value):
                error = int(dut.error.value)
            else:
                error = 0

        # Check
        if is_impossible:
            if error != 1:
                cocotb.log.error(f"Test {t_idx+1}: Expected error flag, got error={error}")
                failed += 1
            else:
                passed += 1
        else:
            if error == 1:
                cocotb.log.error(f"Test {t_idx+1}: Unexpected error flag")
                failed += 1
            elif result != expected:
                cocotb.log.error(f"Test {t_idx+1}: Expected {expected}, got {result}")
                failed += 1
            else:
                passed += 1

    if failed:
        raise TestFailure(f"{failed} tests failed out of {passed + failed}")
    else:
        cocotb.log.info(f"All {passed} tests passed")

