from cocotb.clock import Clock
from cocotb.result import TestFailure

# Constants for n=16
DATA_WIDTH = 1
N = 16
CLK_NS = 10
MAX_CYCLES = 2000

# Helpers

def is_value_defined(v):
    try: int(v); return True
    except ValueError: return False

def safe_int(v, default=0):
    try: return int(v)
    except ValueError: return default

def clamp_to_width(v, bits):
    return min((1 << bits) - 1, max(0, v))

def has_signal(dut, name):
    try: getattr(dut, name); return True
    except AttributeError: return False

# Convert 2D adjacency matrix to packed 1D vector for HDL
# adj[i][j] -> bit index i*16 + j

def pack_adj(adj_matrix):
    packed = 0
    for i in range(N):
        for j in range(N):
            if adj_matrix[i][j] == 1:
                idx = i * N + j
                packed |= (1 << idx)
    return packed

# Parse input string to get adj matrix and S list

def parse_input(input_str):
    lines = input_str.strip().split('\n')
    first_line = lines[0].split()
    n = int(first_line[0])
    k = int(first_line[1])

    adj_matrix = []
    for i in range(n):
        row = list(map(int, lines[i+1].split()))
        adj_matrix.append(row)

    s_list = list(map(int, lines[n+1].split()))
    return n, k, adj_matrix, s_list

# Create S mask

def create_s_mask(s_list):
    mask = 0
    for s in s_list:
        mask |= (1 << s)
    return mask

# Cycle check logic (simulating HDL Kahn's algorithm)
# Returns True if acyclic

def is_dag(adj_packed, active_mask, n):
    # Compute in-degrees for active nodes
    in_degree = {}
    nodes = []

    # Extract nodes
    for i in range(n):
        if (active_mask >> i) & 1:
            nodes.append(i)
            in_degree[i] = 0

    if not nodes:
        return True

    # Calculate in-degrees
    for i in nodes:
        for j in nodes:
            if i == j: continue
            # Check if edge i -> j exists (adj[i][j] = 1)
            idx = i * n + j
            if (adj_packed >> idx) & 1:
                in_degree[j] += 1

    # Kahn's algorithm
    queue = [n for n in nodes if in_degree[n] == 0]
    count = 0

    while queue:
        u = queue.pop(0)
        count += 1
        for v in nodes:
            if u == v: continue
            idx = u * n + v
            if (adj_packed >> idx) & 1:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    queue.append(v)

    return count == len(nodes)

