        ("VV\\\\nVV", 2, 2, 0, 1, "Sample 3: 0 rotations"),
        (".\\\\n.", 1, 1, 0, 1, "1x1 empty"),
        ("V", 1, 1, 0, 1, "1x1 V gargoyle"),
    ]

    passed = 0
    failed = 0

    for i, (grid_str, n, m, exp_result, exp_valid, desc) in enumerate(test_cases):
        cocotb.log.info(f"Test {i+1}: {desc}")
        try:
            # Pack grid into 64-bit input
