def pack_edges(edges, max_edges=64):
    """Pack list of (src, dst) tuples into a list of 8-bit integers."""
    packed = []
    for i in range(max_edges):
        if i < len(edges):
            src, dst = edges[i]
            # 0-indexed for hardware
            packed.append((src << 4) | dst)
        else:
            packed.append(0)
    return packed

