import cocotb
from cocotb.triggers import Timer, RisingEdge
from cocotb.clock import Clock
from cocotb.result import TestFailure
import random

DATA_WIDTH = 32
N_MAX = 16
CLK_NS = 10
MAX_CYCLES = 5000

def is_value_defined(v):
    try:
        int(v)
        return True
    except (ValueError, TypeError):
        return False

def safe_int(v, default=0):
    try:
        return int(v)
    except (ValueError, TypeError):
        return default

def to_signed(val, bits):
    return val - (1 << bits) if val >= (1 << (bits - 1)) else val

def from_signed(val, bits):
    return val + (1 << bits) if val < 0 else val

def has_signal(dut, name):
    try:
        getattr(dut, name)
        return True
    except AttributeError:
        return False

def clamp_to_width(v, bits):
    return min((1 << bits) - 1, max(0, v))

async def reset_dut(dut, cycles=2):
    dut.rst_n.value = 0
    if has_signal(dut, 'start'):
        dut.start.value = 0
    for _ in range(cycles):
        await RisingEdge(dut.clk)
    dut.rst_n.value = 1
    await RisingEdge(dut.clk)

async def wait_for_done(dut, max_cycles=MAX_CYCLES):
    for _ in range(max_cycles):
        await RisingEdge(dut.clk)
        if is_value_defined(dut.valid.value) and int(dut.valid.value) == 1:
            return True
        if is_value_defined(dut.impossible.value) and int(dut.impossible.value) == 1:
            return True
    raise TestFailure(f"Timeout after {max_cycles} cycles")

def compute_results(a, b):
    """Compute +, -, * results for pair (a,b) as 32-bit signed"""
    res = []
    # Addition
    res.append((0, to_signed(a + b, DATA_WIDTH)))
    # Subtraction
    res.append((1, to_signed(a - b, DATA_WIDTH)))
    # Multiplication (truncate to 32-bit)
    prod = a * b
    res.append((2, to_signed(prod & ((1 << DATA_WIDTH) - 1), DATA_WIDTH)))
    return res

@cocotb.test(timeout_time=10000, timeout_unit="ms")
async def test_distinct_results(dut):
    is_seq = has_signal(dut, 'clk')
    if is_seq:
        cocotb.start_soon(Clock(dut.clk, CLK_NS, units='ns').start())
        await reset_dut(dut)

    # Test case 1: Simple case from sample
    test_cases = [
        {
            'n': 4,
            'pairs': [(1, 5), (3, 3), (4, 5), (-1, -6)],
            'expected': 'impossible'
        },
        {
            'n': 3,
            'pairs': [(1, 2), (3, 4), (5, 6)],
            'expected': 'possible'
        },
        {
            'n': 2,
            'pairs': [(0, 0), (1, 1)],
            'expected': 'possible'
        },
        {
            'n': 1,
            'pairs': [(100, 200)],
            'expected': 'possible'
        }
    ]

    passed = 0
    failed = 0

    for test_idx, test in enumerate(test_cases):
        n = test['n']
        pairs = test['pairs']
        expected = test['expected']

        cocotb.log.info(f"Test {test_idx + 1}: n={n}, pairs={pairs}")

        try:
            if is_seq:
                # Set n
                dut.n.value = n

                # Set a and b arrays
                for i in range(N_MAX):
                    if i < n:
                        a_val = pairs[i][0]
                        b_val = pairs[i][1]
                    else:
                        a_val = 0
                        b_val = 0

                    if has_signal(dut, f'a_{i}'):
                        getattr(dut, f'a_{i}').value = clamp_to_width(from_signed(a_val, DATA_WIDTH), DATA_WIDTH)
                        getattr(dut, f'b_{i}').value = clamp_to_width(from_signed(b_val, DATA_WIDTH), DATA_WIDTH)
                    else:
                        # Try array access
                        try:
                            dut.a[i].value = clamp_to_width(from_signed(a_val, DATA_WIDTH), DATA_WIDTH)
                            dut.b[i].value = clamp_to_width(from_signed(b_val, DATA_WIDTH), DATA_WIDTH)
                        except:
                            pass

                # Start processing
                dut.start.value = 1
                await RisingEdge(dut.clk)
                dut.start.value = 0

                # Wait for done
                await wait_for_done(dut)

                # Check results
                if is_value_defined(dut.impossible.value) and int(dut.impossible.value) == 1:
                    result_state = 'impossible'
                else:
                    result_state = 'possible'

                if result_state != expected:
                    raise TestFailure(f"Expected '{expected}', got '{result_state}'")

                # If possible, verify distinct results
                if result_state == 'possible':
                    results = []
                    for i in range(n):
                        if has_signal(dut, f'result_{i}'):
                            res_val = int(getattr(dut, f'result_{i}').value)
                        else:
                            res_val = int(dut.result[i].value)

                        # Convert from unsigned to signed
                        res_signed = to_signed(res_val, DATA_WIDTH)
                        results.append(res_signed)

                    if len(results) != len(set(results)):
                        raise TestFailure(f"Results not distinct: {results}")

                    # Verify against input pairs
                    for i, (a, b) in enumerate(pairs):
                        if has_signal(dut, f'op_{i}'):
                            op_val = int(getattr(dut, f'op_{i}').value)
                        else:
                            op_val = int(dut.op[i].value)

                        if has_signal(dut, f'result_{i}'):
                            res_val = int(getattr(dut, f'result_{i}').value)
                        else:
                            res_val = int(dut.result[i].value)

                        res_signed = to_signed(res_val, DATA_WIDTH)

                        if op_val == 0:
                            expected_res = to_signed(a + b, DATA_WIDTH)
                        elif op_val == 1:
                            expected_res = to_signed(a - b, DATA_WIDTH)
                        else:  # op_val == 2
                            prod = a * b
                            expected_res = to_signed(prod & ((1 << DATA_WIDTH) - 1), DATA_WIDTH)

                        if res_signed != expected_res:
                            raise TestFailure(f"Pair {i}: op={op_val} gave {res_signed}, expected {expected_res}")

                passed += 1
                cocotb.log.info(f"Test {test_idx + 1} passed")
            else:
                # Combinational test
                await Timer(100, units='ns')
                passed += 1

        except TestFailure as e:
            cocotb.log.error(f"Test {test_idx + 1} FAILED: {e}")
            failed += 1

    # Additional stress test with random valid input
    cocotb.log.info("Running random stress test...")
    try:
        if is_seq:
            n = 4
            pairs = [(random.randint(-100, 100), random.randint(-100, 100)) for _ in range(n)]

            dut.n.value = n
            for i in range(N_MAX):
                if i < n:
                    a_val = pairs[i][0]
                    b_val = pairs[i][1]
                else:
                    a_val = 0
                    b_val = 0

                if has_signal(dut, f'a_{i}'):
                    getattr(dut, f'a_{i}').value = clamp_to_width(from_signed(a_val, DATA_WIDTH), DATA_WIDTH)
                    getattr(dut, f'b_{i}').value = clamp_to_width(from_signed(b_val, DATA_WIDTH), DATA_WIDTH)
                else:
                    try:
                        dut.a[i].value = clamp_to_width(from_signed(a_val, DATA_WIDTH), DATA_WIDTH)
                        dut.b[i].value = clamp_to_width(from_signed(b_val, DATA_WIDTH), DATA_WIDTH)
                    except:
                        pass

            dut.start.value = 1
            await RisingEdge(dut.clk)
            dut.start.value = 0
            await wait_for_done(dut)

            if is_value_defined(dut.impossible.value) and int(dut.impossible.value) == 1:
                # May be impossible for random input, that's ok
                cocotb.log.info("Random test: impossible (valid outcome)")
            else:
                results = []
                for i in range(n):
                    if has_signal(dut, f'result_{i}'):
                        res_val = int(getattr(dut, f'result_{i}').value)
                    else:
                        res_val = int(dut.result[i].value)
                    res_signed = to_signed(res_val, DATA_WIDTH)
                    results.append(res_signed)

                if len(results) != len(set(results)):
                    raise TestFailure("Random test: results not distinct")
                cocotb.log.info(f"Random test passed: results={results}")

            passed += 1
        else:
            await Timer(100, units='ns')
            passed += 1

    except TestFailure as e:
        cocotb.log.error(f"Random stress test FAILED: {e}")
        failed += 1

    cocotb.log.info(f"Final result: {passed} passed, {failed} failed")
    if failed > 0:
        raise TestFailure(f"{failed} tests failed")

import cocotb
from cocotb.triggers import Timer, RisingEdge
from cocotb.clock import Clock
from cocotb.result import TestFailure

# Constants
DATA_WIDTH = 32
MAX_CYCLES = 200

# Helpers

def is_value_defined(v):
    try:
        int(v)
        return True
    except (ValueError, TypeError):
        return False

def clamp_to_width(v, bits):
    if not isinstance(v, int):
        v = 0
    return min((1 << bits) - 1, max(0, v))

def has_signal(dut, name):
    try:
        getattr(dut, name)
        return True
    except AttributeError:
        return False

async def reset_dut(dut, cycles=2):
    dut.rst_n.value = 0
    if has_signal(dut, 'start'):
        dut.start.value = 0
    for _ in range(cycles):
        await RisingEdge(dut.clk)
    dut.rst_n.value = 1
    await RisingEdge(dut.clk)

async def wait_for_done(dut, max_cycles=MAX_CYCLES):
    for _ in range(max_cycles):
        if has_signal(dut, 'done'):
            await RisingEdge(dut.clk)
            if is_value_defined(dut.done.value) and int(dut.done.value) == 1:
                return True
        else:
            # If no done signal, assume combinational after delay
            await Timer(100, units='ns')
            return True
    raise TestFailure(f"Timeout after {max_cycles} cycles")

@cocotb.test(timeout_time=2000, timeout_unit="ms")
async def test_football_cheer(dut):
    # Setup Clock
    if has_signal(dut, 'clk'):
        cocotb.start_soon(Clock(dut.clk, 10, units='ns').start())
        await reset_dut(dut)
    else:
        await Timer(10, units='ns')

    # Test Cases
    # Case 1: n=1, t=31, Opponent: [20,60], [50,90]
    # Opponent active minutes: 20-59 (40 mins), 50-89 (40 mins) -> Union: 20-89 (70 mins)
    # We have 31 minutes. We should cheer to create 5-streaks.
    # Optimal (from python logic): 4 goals for us, 3 for them (Sample Output 4 3)

    test_cases = [
        {
            'n': 1,
            't': 31,
            'opp_ranges': [(20, 60), (50, 90)],
            'exp_a': 4,
            'exp_b': 3,
            'desc': 'Sample 1'
        },
        {
            'n': 2,
            't': 5,
            'opp_ranges': [(0, 90), (0, 90), (3, 90)],
            'exp_a': 0,
            'exp_b': 17,
            'desc': 'Sample 2'
        }
    ]

    for tc in test_cases:
        cocotb.log.info(f"Running test: {tc['desc']}")

        # Generate opponent bitmask (90 bits)
        opp_mask = [0] * 90
        for (start, end) in tc['opp_ranges']:
            for i in range(start, end):
                if i < 90:
                    opp_mask[i] = 1

        # Pack into 32-bit chunks for HDL
        # Input names might be opp_low, opp_mid, opp_high or just opp array
        # We check for specific signal names or generic interface

        if has_signal(dut, 'opponent_low'):
            low = 0; mid = 0; high = 0
            for i in range(32):
                if i < 90 and opp_mask[i]: low |= (1 << i)
            for i in range(32):
                if 32+i < 90 and opp_mask[32+i]: mid |= (1 << i)
            for i in range(26): # 64 to 89
                if 64+i < 90 and opp_mask[64+i]: high |= (1 << i)

            dut.opponent_low.value = low
            dut.opponent_mid.value = mid
            dut.opponent_high.value = high

        elif has_signal(dut, 'opponent'): # Array interface
            for i in range(90):
                dut.opponent[i].value = opp_mask[i]

        if has_signal(dut, 'n'):
            dut.n.value = tc['n']
        if has_signal(dut, 't'):
            dut.t.value = tc['t']

        # Start
        if has_signal(dut, 'start'):
            dut.start.value = 1
            await RisingEdge(dut.clk)
            dut.start.value = 0
            await wait_for_done(dut)
        else:
            await Timer(100, units='ns')

        # Check Results
        try:
            if has_signal(dut, 'sportify_score'):
                score_a = int(dut.sportify_score.value)
            else:
                score_a = -1

            if has_signal(dut, 'spoilify_score'):
                score_b = int(dut.spoilify_score.value)
            else:
                score_b = -1

            if score_a != tc['exp_a'] or score_b != tc['exp_b']:
                raise TestFailure(f"Mismatch: Expected ({tc['exp_a']}, {tc['exp_b']}), Got ({score_a}, {score_b})")

            cocotb.log.info(f"PASS: {tc['desc']} - Result {score_a} {score_b}")

        except Exception as e:
            cocotb.log.error(f"FAIL: {tc['desc']} - {e}")
            raise

import cocotb
from cocotb.triggers import Timer, RisingEdge
from cocotb.clock import Clock
from cocotb.result import TestFailure
import math

DATA_WIDTH = 24  # Q8.16 fixed-point
NODE_WIDTH = 4
MAX_NODES = 16
CLK_NS = 10
MAX_CYCLES = 1500

def is_value_defined(v):
    try:
        int(v)
        return True
    except ValueError:
        return False

def safe_int(v, default=0):
    try:
        return int(v)
    except ValueError:
        return default

def has_signal(dut, name):
    try:
        getattr(dut, name)
        return True
    except AttributeError:
        return False

def clamp_to_width(v, bits):
    if v < 0:
        return 0
    max_val = (1 << bits) - 1
    return min(max_val, v)

def float_to_q8_16(f, scale=1.0):
    """Convert float to Q8.16 fixed-point integer"""
    val = int(f * scale * 256)  # 256 = 2^8
    return clamp_to_width(val, DATA_WIDTH)

def q8_16_to_int(v):
    """Convert Q8.16 to integer (round)"""
    return int(v >> 16) + (1 if (v & 0x8000) else 0)

def pack_results(results, width=16, count=16):
    """Pack 16-bit results into 256-bit value"""
    packed = 0
    for i in range(count):
        packed |= (results[i] & ((1 << width) - 1)) << (i * width)
    return packed

def calc_abs_diff(x1, x2):
    """Calculate absolute difference in Q8.16"""
    diff = abs(x1 - x2)
    return diff

async def wait_for_done(dut, max_cycles=MAX_CYCLES):
    for i in range(max_cycles):
