# For sorting median calculation
def compute_median(densities):
    if not densities:
        return 0.0
    sorted_d = sorted(densities)
    n = len(sorted_d)
    mid = n // 2
    if n % 2 == 1:
        return sorted_d[mid]
    else:
        return (sorted_d[mid-1] + sorted_d[mid]) / 2.0

