    ]

    passed = 0
    failed = 0

    for L, R, desc in test_cases:
        # Scale down for Verilog if needed, keep small
        # Python reference
        exp = python_counts(L, R)

        cocotb.log.info(f"Test {desc}: L={L}, R={R}")
        cocotb.log.info(f"Expected: {exp}")

