# Constants
DATA_WIDTH = 16
ARRAY_SIZE = 8
CLK_NS = 10
MAX_CYCLES = 2000  # Allow ample time for brute force

# Helper Functions
def is_value_defined(v):
    try:
        int(v)
        return True
    except ValueError:
        return False

def safe_int(v, default=0):
    try:
        return int(v)
    except ValueError:
        return default

def to_signed(val, bits):
    # Convert Python int to 2's complement value if needed, 
    # but Python handles large ints, so just clamp
    if val >= (1 << (bits-1)):
        return val - (1 << bits)
    return val

def from_signed(val, bits):
    # Convert 2's complement to positive Python int if negative
    if val < 0:
        return val + (1 << bits)
    return val

def has_signal(dut, name):
    try:
        getattr(dut, name)
        return True
    except AttributeError:
        return False

def clamp_to_width(v, bits):
    # Clamp to signed range -2^(n-1) to 2^(n-1)-1
    min_val = -(1 << (bits - 1))
    max_val = (1 << (bits - 1)) - 1
    if v > max_val: return max_val
    if v < min_val: return min_val
    return v

async def reset_dut(dut):
    dut.rst_n.value = 0
    if has_signal(dut, 'start'):
        dut.start.value = 0
    if has_signal(dut, 'valid_in'):
        dut.valid_in.value = 0
    for _ in range(2):
        await RisingEdge(dut.clk)
    dut.rst_n.value = 1
    await RisingEdge(dut.clk)

