import cocotb
from cocotb.triggers import Timer, RisingEdge
from cocotb.clock import Clock
from cocotb.result import TestFailure

# Constants for scaled problem
MAX_MSG_LEN = 8
MAX_STICKERS = 16
STICKER_WIDTH = 6
DATA_WIDTH = 8
CLK_NS = 10
MAX_CYCLES = 500

# Helper functions
def is_value_defined(v):
    try:
        int(v)
        return True
    except (ValueError, TypeError):
        return False

def safe_int(v, default=0):
    try:
        return int(v)
    except (ValueError, TypeError):
        return default

def clamp_to_width(v, bits):
    return min((1 << bits) - 1, max(0, v))

def has_signal(dut, name):
    try:
        getattr(dut, name)
        return True
    except AttributeError:
        return False

def to_q16_16(f):
    """Convert float to Q16.16 fixed point"""
    return int(f * (1 << 16))

def from_q16_16(v):
    """Convert Q16.16 fixed point to float"""
    return v / (1 << 16)

def encode_sticker(chars, start, end, price):
    """Pack sticker into 64-bit: {start:3b, end:3b, price:16b, chars:32b}"""
    char_bits = 0
    for i, c in enumerate(chars):
        if i < 4:  # 4 chars max for 32-bit field (8 bits each)
            char_bits |= (ord(c) << (i * 8))
    start_bit = start & 0x7
    end_bit = end & 0x7
    price_bits = clamp_to_width(price, 16)
    return (char_bits | (price_bits << 32) | (end_bit << 48) | (start_bit << 51)) & 0xFFFFFFFFFFFFFFFF

def encode_msg(msg):
    """Encode message as list of 8-bit chars, padded to 8"""
    result = [ord(c) for c in msg[:MAX_MSG_LEN]]
    while len(result) < MAX_MSG_LEN:
        result.append(0)  # Null terminator
    return result

async def reset_dut(dut, cycles=2):
    if has_signal(dut, 'rst_n'):
        dut.rst_n.value = 0
    if has_signal(dut, 'start'):
        dut.start.value = 0
    if has_signal(dut, 'msg_valid'):
        dut.msg_valid.value = 0
    if has_signal(dut, 'sticker_valid'):
        dut.sticker_valid.value = 0

    for _ in range(cycles):
        await RisingEdge(dut.clk)

    if has_signal(dut, 'rst_n'):
        dut.rst_n.value = 1
    await RisingEdge(dut.clk)

async def wait_for_done(dut, max_cycles=MAX_CYCLES):
    for _ in range(max_cycles):
        await RisingEdge(dut.clk)
        if has_signal(dut, 'done') and is_value_defined(dut.done.value) and int(dut.done.value) == 1:
            return True
    raise TestFailure(f"Timeout after {max_cycles} cycles")

async def load_message(dut, msg_str):
    """Load message character by character"""
    encoded = encode_msg(msg_str)
    for i, char in enumerate(encoded):
        if has_signal(dut, 'msg_valid'):
            dut.msg_valid.value = 1
        if has_signal(dut, 'msg_data'):
            dut.msg_data.value = clamp_to_width(char, 8)
        await RisingEdge(dut.clk)
    if has_signal(dut, 'msg_valid'):
        dut.msg_valid.value = 0

async def load_sticker(dut, chars, start, end, price):
    """Load one sticker"""
    sticker_bits = encode_sticker(chars, start, end, price)
    if has_signal(dut, 'sticker_valid'):
        dut.sticker_valid.value = 1
    if has_signal(dut, 'sticker_data'):
        dut.sticker_data.value = sticker_bits
    await RisingEdge(dut.clk)
    if has_signal(dut, 'sticker_valid'):
        dut.sticker_valid.value = 0

@cocotb.test(timeout_time=10000, timeout_unit="ms")
async def test_sticker_message(dut):
    """Test the sticker message processor"""

    # Setup clock
    if has_signal(dut, 'clk'):
        cocotb.start_soon(Clock(dut.clk, CLK_NS, units='ns').start())
        await reset_dut(dut)
    else:
        # Combinational module
        await Timer(10, units='ns')

    # Test cases: (message, stickers_list, expected_cost, desc, should_be_impossible)
    test_cases = [
        (
            "BUYRICK",  # Shortened from BUYSTICKERS
            [("BUYER", 0, 4, 10.0), ("STICKY", 2, 7, 10.0), ("TICKERS", 3, 7, 1.0), ("ERS", 5, 7, 8.0)],
            28.0,
            "Example case",
            False
        ),
        (
            "ABBBAA",  # Extended ABBA for 8 chars
            [("AAAAA", 0, 4, 10.0), ("BB", 2, 3, 3.0)],
            0.0,
            "Impossible case (modified)",
            True
        ),
        (
            "AAAAAAA",  # All same letters
            [("AAAAA", 0, 4, 5.0), ("AAA", 0, 2, 2.0), ("AA", 3, 4, 1.0), ("A", 0, 0, 0.5)],
            7.5,
            "Simple overlapping",
            False
        )
    ]

    passed = 0
    failed = 0

    for test_idx, (msg, stickers, exp_cost, desc, should_be_impossible) in enumerate(test_cases):
        cocotb.log.info(f"\nTest {test_idx + 1}: {desc}")
        cocotb.log.info(f"  Message: {msg}")
        cocotb.log.info(f"  Stickers: {len(stickers)} types")

        try:
            # Reset for each test
            if has_signal(dut, 'rst_n'):
                await reset_dut(dut, cycles=2)
            else:
                await Timer(100, units='ns')

            # Load message
            if has_signal(dut, 'msg_data') or has_signal(dut, 'msg_valid'):
                await load_message(dut, msg)

            # Load stickers
            if has_signal(dut, 'sticker_data'):
                for chars, start, end, price in stickers:
                    # Scale for 8-char message
                    scale_factor = MAX_MSG_LEN / len(msg)
                    start_scaled = int(start * scale_factor)
                    end_scaled = int(end * scale_factor)
                    if end_scaled >= MAX_MSG_LEN:
                        end_scaled = MAX_MSG_LEN - 1
                    if start_scaled < 0:
                        start_scaled = 0
                    if start_scaled >= MAX_MSG_LEN:
                        start_scaled = MAX_MSG_LEN - 1
                    if end_scaled < start_scaled:
                        end_scaled = start_scaled

                    # Truncate chars to fit 6-char limit for scaled problem
                    chars_truncated = chars[:STICKER_WIDTH]

                    await load_sticker(dut, chars_truncated, start_scaled, end_scaled, price)

            # Start processing
            if has_signal(dut, 'start'):
                dut.start.value = 1
                await RisingEdge(dut.clk)
                dut.start.value = 0
            else:
                # Combinational: wait for calculation
                await Timer(100, units='ns')

            # Wait for done
            if has_signal(dut, 'done'):
                await wait_for_done(dut, max_cycles=MAX_CYCLES)

            # Read results
            result_cost = 0
            impossible = 0

            if has_signal(dut, 'impossible') and is_value_defined(dut.impossible.value):
                impossible = int(dut.impossible.value)

            if has_signal(dut, 'result_cost') and is_value_defined(dut.result_cost.value):
                result_cost = int(dut.result_cost.value)

            if has_signal(dut, 'result_valid') and is_value_defined(dut.result_valid.value):
                if int(dut.result_valid.value) == 0:
                    raise TestFailure("Result valid flag is 0")

            # Check results
            if should_be_impossible:
                if impossible != 1:
                    raise TestFailure(f"Expected IMPOSSIBLE, but got cost = {result_cost}")
                cocotb.log.info(f"  ✓ Correctly returned IMPOSSIBLE")
            else:
                if impossible == 1:
                    raise TestFailure("Expected cost, but got IMPOSSIBLE")

                # Compare costs with tolerance for fixed-point
                exp_cost_q16 = to_q16_16(exp_cost)
                result_q16 = result_cost

                # Allow small rounding errors
                tolerance = 100  # ~0.0015 in Q16.16
                if abs(result_q16 - exp_cost_q16) > tolerance:
                    raise TestFailure(f"Expected {exp_cost} ({exp_cost_q16}), got {from_q16_16(result_q16)} ({result_q16})")

                cocotb.log.info(f"  ✓ Correct cost: {from_q16_16(result_q16)}")

            passed += 1

        except TestFailure as e:
            cocotb.log.error(f"  FAIL: {e}")
            failed += 1

        await Timer(100, units='ns')  # Small gap between tests

    if failed > 0:
        raise TestFailure(f"{failed} of {len(test_cases)} tests failed")

    cocotb.log.info(f"\n✓ All {passed} tests passed")

import cocotb
from cocotb.triggers import Timer, RisingEdge
from cocotb.clock import Clock
from cocotb.result import TestFailure
import math

# Constants
WELLS_MAX = 1000
PIPES_MAX = 1000
COORD_WIDTH = 17  # 13 bits for 8192, plus sign
INDEX_WIDTH = 10  # for 1024 elements
DATA_WIDTH = 16
CLK_NS = 10
MAX_CYCLES = 100000

# Helper functions
def is_value_defined(v):
    try:
        int(v)
        return True
    except ValueError:
        return False

def safe_int(v, default=0):
    try:
        return int(v)
    except ValueError:
        return default

def clamp_to_width(v, bits):
    min_val = -(1 << (bits-1)) if bits > 0 else 0
    max_val = (1 << bits) - 1 if bits > 0 else 0
    if v < min_val:
        return min_val
    if v > max_val:
        return max_val
    return v

def has_signal(dut, name):
    try:
        getattr(dut, name)
        return True
    except AttributeError:
        return False

def from_signed(val, bits):
    if val < 0:
        return val + (1 << bits)
    return val

# Geometry helper for testing
def check_intersection(p1_start, p1_end, p2_start, p2_end, wells):
    """Check if two pipe segments intersect (not at a well)"""
    x1, y1 = p1_start
    x2, y2 = p1_end
    x3, y3 = p2_start
    x4, y4 = p2_end

    def cross_product(x1, y1, x2, y2, x3, y3):
        return (x2 - x1) * (y3 - y1) - (y2 - y1) * (x3 - x1)

    def on_segment(x1, y1, x2, y2, x3, y3):
        if min(x1, x2) <= x3 <= max(x1, x2) and min(y1, y2) <= y3 <= max(y1, y2):
            return True
        return False

    d1 = cross_product(x1, y1, x2, y2, x3, y3)
    d2 = cross_product(x1, y1, x2, y2, x4, y4)
    d3 = cross_product(x3, y3, x4, y4, x1, y1)
    d4 = cross_product(x3, y3, x4, y4, x2, y2)

    # General case: proper intersection
    if ((d1 > 0 and d2 < 0) or (d1 < 0 and d2 > 0)) and \
       ((d3 > 0 and d4 < 0) or (d3 < 0 and d4 > 0)):
        return True

    # Special cases: collinear
    if d1 == 0 and on_segment(x1, y1, x2, y2, x3, y3):
        if not is_well_point((x3, y3), wells):
            return True
    if d2 == 0 and on_segment(x1, y1, x2, y2, x4, y4):
        if not is_well_point((x4, y4), wells):
            return True
    if d3 == 0 and on_segment(x3, y3, x4, y4, x1, y1):
        if not is_well_point((x1, y1), wells):
            return True
    if d4 == 0 and on_segment(x3, y3, x4, y4, x2, y2):
        if not is_well_point((x2, y2), wells):
            return True

    return False

def is_well_point(point, wells):
    x, y = point
    for wx, wy in wells:
        if x == wx and y == wy:
            return True
    return False

def build_graph(pipes, wells):
    """Build adjacency list for intersection graph"""
    n = len(pipes)
    adj = [[] for _ in range(n)]

    for i in range(n):
        for j in range(i + 1, n):
            s1, e1x, e1y = pipes[i]
            s2, e2x, e2y = pipes[j]
            w1x, w1y = wells[s1 - 1]
            w2x, w2y = wells[s2 - 1]

            if check_intersection((w1x, w1y), (e1x, e1y), (w2x, w2y), (e2x, e2y), wells):
                adj[i].append(j)
                adj[j].append(i)

    return adj

def is_bipartite(adj):
    """Check if graph is bipartite using BFS"""
    n = len(adj)
    if n == 0:
        return True

    color = [-1] * n

    for start in range(n):
        if color[start] == -1:
            color[start] = 0
            queue = [start]

            while queue:
                u = queue.pop(0)
                for v in adj[u]:
                    if color[v] == -1:
                        color[v] = 1 - color[u]
                        queue.append(v)
                    elif color[v] == color[u]:
                        return False

    return True

def write_array(dut, name, values, width):
    """Write values to array elements"""
    for i, v in enumerate(values):
        setattr(dut, f"{name}[{i}]").value = clamp_to_width(v, width)

def write_individual_arrays(dut, wells, pipes):
    """Write individual well and pipe arrays"""
    for i, (wx, wy) in enumerate(wells):
        getattr(dut, f"well_x[{i}]").value = from_signed(clamp_to_width(wx, COORD_WIDTH), COORD_WIDTH)
        getattr(dut, f"well_y[{i}]").value = from_signed(clamp_to_width(wy, COORD_WIDTH), COORD_WIDTH)

    for i, (s, ex, ey) in enumerate(pipes):
        getattr(dut, f"pipe_start[{i}]").value = clamp_to_width(s, INDEX_WIDTH)
        getattr(dut, f"pipe_end_x[{i}]").value = from_signed(clamp_to_width(ex, COORD_WIDTH), COORD_WIDTH)
        getattr(dut, f"pipe_end_y[{i}]").value = from_signed(clamp_to_width(ey, COORD_WIDTH), COORD_WIDTH)

