# Test solver in Python for verification
def solve_python(n, m, grid):
    best = None
    best_moves = float('inf')
    best_is_rows = None
    best_r = None
    best_c = None
    best_x = None

    for x in range(16):
        c = [grid[0][j] - x for j in range(m)]
        if any(val < 0 for val in c):
            continue

        r = []
        valid = True
        for i in range(n):
            row_min = float('inf')
            for j in range(m):
                diff = grid[i][j] - c[j]
                if diff < 0:
                    valid = False
                    break
                row_min = min(row_min, diff)
            if not valid:
                break
            r.append(row_min)

        if not valid:
            continue

        # Verify
        for i in range(n):
            for j in range(m):
                if r[i] + c[j] + x != grid[i][j]:
                    valid = False
                    break
            if not valid:
                break

        if valid:
            moves = x * min(n, m) + sum(r) + sum(c)
            if moves < best_moves:
                best_moves = moves
                best_is_rows = n <= m
                best_r = r
                best_c = c
                best_x = x

    if best is None:
        return (-1, None, None, None)

    # Generate moves
    moves_list = []
    if best_is_rows:
        for i in range(n):
            for _ in range(best_r[i]):
                moves_list.append(f"row {i+1}")
        for j in range(m):
            for _ in range(best_c[j]):
                moves_list.append(f"col {j+1}")
        for _ in range(best_x):
            for i in range(n):
                moves_list.append(f"row {i+1}")
    else:
        for j in range(m):
            for _ in range(best_c[j]):
                moves_list.append(f"col {j+1}")
        for i in range(n):
            for _ in range(best_r[i]):
                moves_list.append(f"row {i+1}")
        for _ in range(best_x):
            for j in range(m):
                moves_list.append(f"col {j+1}")

    return (best_moves, best_r, best_c, moves_list)

