            "expected": 4,
            "desc": "Problem Ex 1: Square cycle"
        },
        {
            "vals": [1, 2, 4, 8],
            "expected": -1,
            "desc": "Problem Ex 3: No cycle"
        },
        {
            "vals": [7, 7, 7], # All share bits
            "expected": 3,
            "desc": "Triangle via bit 0"
        },
        {
