def compute_expected(n, a, p):
    if sum(a) <= p:
        return float(n)
    fact = [1] * 51
    for i in range(1, 51):
        fact[i] = fact[i-1] * i
    total_ans = 0
    for i in range(n):
        dp = [[0] * (p + 2) for _ in range(n)]
        dp[0][0] = 1
        for guest_idx in range(n):
            if guest_idx == i:
                continue
            size = a[guest_idx]
            for k in range(n-2, -1, -1):
                for z in range(p, -1, -1):
                    if dp[k][z] > 0:
                        new_sum = z + size
                        if new_sum <= p:
                            dp[k+1][new_sum] += dp[k][z]
        for k in range(n):
            for z in range(p + 1):
                if z + a[i] > p:
                    count = dp[k][z]
                    if count > 0:
                        total_ans += k * count * fact[k] * fact[n - 1 - k]
    return total_ans / fact[n]

