            # Check result
            if not is_value_defined(dut.valid.value):
                raise TestFailure("Valid signal undefined")

            result_valid = int(dut.valid.value) == 1

            if result_valid:
                # Read output vertices
                output_verts = []
                for vert_idx in range(8):
                    v = []
                    for coord_idx in range(3):
