def compute_expected(n, p):
    pos = [0] * (n + 1)
    for i, val in enumerate(p):
        pos[val] = i
    max_len = 1
    cur_len = 1
    for v in range(2, n + 1):
        if pos[v] > pos[v - 1]:
            cur_len += 1
        else:
            if cur_len > max_len:
                max_len = cur_len
            cur_len = 1
    if cur_len > max_len:
        max_len = cur_len
    return n - max_len

