        await ClockCycles(dut.clk, 2) if has_signal(dut, 'clk') else Timer(20, units='ns')
        dut.rst_n.value = 1
        if has_signal(dut, 'clk'): await RisingEdge(dut.clk)
    else:
        await Timer(10, units='ns')

