MOD = 10**9 + 7

# Helper functions

def is_value_defined(v):
    try:
        int(v)
        return True
    except:
        return False

def safe_int(v, default=0):
    try:
        return int(v)
    except:
        return default

def clamp_to_width(v, bits):
    max_val = (1 << bits) - 1
    return min(max_val, max(0, v))

def has_signal(dut, name):
    try:
        getattr(dut, name)
        return True
    except AttributeError:
        return False

def from_signed(val, bits):
    if val < 0:
        return val + (1 << bits)
    return val

# Python reference implementation
def solve_python(N, K, MOD):
    # Find divisors
    div = []
    i = 1
    while i * i <= N:
        if N % i == 0:
            div.append(i)
            if i * i != N:
                div.append(N // i)
        i += 1
    div.sort()

    # Compute f(d) = K^ceil(d/2)
    f = {}
    for d in div:
        exp = (d + 1) // 2
        f[d] = pow(K, exp, MOD)

    # Inclusion-exclusion to get f_clean
    f_clean = {}
    for d in div:
        val = f[d]
        for e in div:
            if e >= d:
                break
            if d % e == 0:
                val = (val - f_clean[e]) % MOD
        f_clean[d] = val

    # Sum contributions
    ans = 0
    for d in div:
        if d % 2 == 0:
            contrib = (d // 2) * f_clean[d]
        else:
            contrib = d * f_clean[d]
        ans = (ans + contrib) % MOD

    return ans

async def write_divisors(dut, divisors):
    """Write divisors to internal array"""
    for i, d in enumerate(divisors[:256]):
        if hasattr(dut, f'div_array_{i}'):
            getattr(dut, f'div_array_{i}').value = clamp_to_width(d, 16)
        elif hasattr(dut, 'div_array'):
            dut.div_array[i].value = clamp_to_width(d, 16)

