def pack_array(vals, bits=8):
    r = 0
    for i, v in enumerate(vals):
        r |= (v & ((1 << bits) - 1)) << (i * bits)
    return r

@cocotb.test(timeout_time=5000, timeout_unit="ms")
async def test_module(dut):
    # Check if sequential
    is_seq = has_signal(dut, 'clk')

