import cocotb
from cocotb.triggers import Timer, RisingEdge
from cocotb.clock import Clock
from cocotb.result import TestFailure
import random

DATA_WIDTH = 8
MAX_N = 16
MAX_M = 16
CLK_NS = 10
MAX_CYCLES = 1000

# Helper functions
def is_value_defined(v):
    try: int(v); return True
    except ValueError: return False

def clamp_to_width(v, bits):
    return min((1 << bits) - 1, max(0, v))

def has_signal(dut, name):
    try: getattr(dut, name); return True
    except AttributeError: return False

def pack_grid(grid, rows, cols, width=DATA_WIDTH):
    packed = 0
    for r in range(rows):
        for c in range(cols):
            val = clamp_to_width(grid[r][c], width)
            index = r * MAX_M + c
            packed |= (val << (index * width))
    return packed

def unpack_result(packed_val, rows, cols, width=DATA_WIDTH):
    res = [[0]*cols for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            index = r * MAX_M + c
            shift = index * width
            mask = (1 << width) - 1
            res[r][c] = (packed_val >> shift) & mask
    return res

def get_expected(grid, n, m):
    # Python reference implementation
    rows = []
    for i in range(n):
        row = set()
        for j in range(m):
            row.add(grid[i][j])
        rows.append({x: i for i, x in enumerate(sorted(row))})

    columns = []
    for j in range(m):
        col = set()
        for i in range(n):
            col.add(grid[i][j])
        columns.append({x: i for i, x in enumerate(sorted(col))})

    ans = []
    for i in range(n):
        row_ans = []
        for j in range(m):
            val = grid[i][j]
            idx1 = rows[i][val]
            idx2 = columns[j][val]
            row_ans.append(max(idx1, idx2) + max(len(rows[i]) - idx1, len(columns[j]) - idx2))
        ans.append(row_ans)
    return ans

