    raise TestFailure(f"Timeout after {max_cycles} cycles")

def solve_py(coords, n):
    if n <= 1:
        return 0
    coords.sort()
    ans = 0
    for i in range(n - 1):
        diff = (coords[i+1] - coords[i]) % MOD
        left = (mod_pow2(i) - 1) % MOD
        right = (mod_pow2(n - 2 - i) - 1) % MOD
        contrib = (diff * left) % MOD
        contrib = (contrib * right) % MOD
        ans = (ans + contrib) % MOD
    return ans

