        dut.start.value = 1
        if has_signal(dut, 'clk'): await RisingEdge(dut.clk)
        dut.start.value = 0

        # Simulate expected output
        exp_result, exp_matches = simulate_ratings(n, init_ratings)

        # Collect matches from DUT
        dut_matches = []

