    """Calculate expected sum and product"""
    if not numbers:
        return 0, 1

    sum_val = 0
    prod_val = 1
    overflow = False

    for num in numbers:
        sum_val += num
        if not overflow:
            if prod_val * num > 0xFFFF:
                overflow = True
                prod_val = 0xFFFF
            else:
                prod_val *= num

    return clamp_to_width(sum_val, OUTPUT_WIDTH), prod_val

