def sum_digits(n):
    s = 0
    while n > 0:
        s += n % 10
        n //= 10
    return s

def is_prime(n):
    if n <= 1: return False
    if n <= 3: return True
    if n % 2 == 0 or n % 3 == 0: return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def python_solve(lst):
    max_prime = 0
    for x in lst:
        if is_prime(x) and x > max_prime:
            max_prime = x
    return sum_digits(max_prime)

