def float_to_q88(f):
    """Convert float to Q8.8 integer (8 frac bits)"""
    return int(f * 256)

def unpack_grades(packed, num_grades):
    """Unpack 4-bit grades from 32-bit vector"""
    grades = []
    for i in range(num_grades):
        grade = (packed >> (i*4)) & 0xF
        grades.append(grade)
    return grades

