# BIT ENCODING FOR ASCII STRINGS (8-byte fixed)
string_lut = {
    1: 0x4F6E650000000000,  # "One\0\0\0\0\0"
    2: 0x54776F0000000000,  # "Two\0\0\0\0\0"
    3: 0x5468726565000000,  # "Three\0\0\0"
