    def reference_find_element(arr, ranges, rotations, index):
        # rotations here matches num_ranges
        for i in range(rotations - 1, -1, -1):
            left = ranges[i][0]
            right = ranges[i][1]
            if left <= index and right >= index:
                if index == left:
                    index = right
                else:
                    index = index - 1
        return arr[index]

