import cocotb
from cocotb.triggers import Timer, RisingEdge
from cocotb.clock import Clock
from cocotb.result import TestFailure
import random

DATA_WIDTH = 8
MAX_ARRAY_SIZE = 8
CLK_NS = 10
MAX_CYCLES = 100

# Helper functions
def is_value_defined(v):
    try:
        int(v)
        return True
    except ValueError:
        return False

def safe_int(v, default=0):
    try:
        return int(v)
    except ValueError:
        return default

def clamp_to_width(v, bits):
    """Clamp value to bit width for unsigned"""
    return min((1 << bits) - 1, max(0, v))

def clamp_signed(v, bits):
    """Clamp signed value to bit width"""
    min_val = -(1 << (bits - 1))
    max_val = (1 << (bits - 1)) - 1
    return min(max_val, max(min_val, v))

def to_signed(val, bits):
    """Convert signed Python int to unsigned for HDL"""
    if val < 0:
        return val + (1 << bits)
    return val

def from_signed(val, bits):
    """Convert unsigned HDL value to signed Python int"""
    if val >= (1 << (bits - 1)):
        return val - (1 << bits)
    return val

def has_signal(dut, name):
    try:
        getattr(dut, name)
        return True
    except AttributeError:
        return False

def pack_array_for_bus(values, bits=8, positions=8):
    """Pack array values into bit representation"""
    packed = 0
    for i in range(min(len(values), positions)):
        val = clamp_signed(values[i], bits)
        packed |= (to_signed(val, bits) & ((1 << bits) - 1)) << (i * bits)
    return packed

async def reset_dut(dut, cycles=2):
    dut.rst_n.value = 0
    if has_signal(dut, 'start'):
        dut.start.value = 0
    for _ in range(cycles):
        await RisingEdge(dut.clk)
    dut.rst_n.value = 1
    await RisingEdge(dut.clk)

async def wait_for_done(dut, max_cycles=1000):
    for _ in range(max_cycles):
        await RisingEdge(dut.clk)
        if is_value_defined(dut.done.value) and int(dut.done.value) == 1:
            return True
    raise TestFailure(f"Timeout after {max_cycles} cycles")

