    if not nums:
        return 0
    freq = {}
    for n in nums:
        freq[n] = freq.get(n, 0) + 1
    # Find max frequency, with tiebreaker to smaller value (first in iteration)
    max_val = None
    max_count = 0
    for val, count in sorted(freq.items()):  # Sort for deterministic tiebreaker
