            # Write array to DUT
            # Handle different array access methods
            if hasattr(dut, 'arr') and hasattr(dut.arr, '__len__'):
                # Packed array or memory
                if len(dut.arr) >= len(clamped_arr):
                    for i, val in enumerate(clamped_arr):
