            else:
                # Individual ports arr_0, arr_1...
                for i in range(ARRAY_SIZE):
                    attr_name = f'arr_{i}'
                    if hasattr(dut, attr_name):
                        if i < len(clamped_arr):
                            getattr(dut, attr_name).value = clamped_arr[i]
                        else:
