    # Map test cases to HDL input format
    # Tuple (4,6) is represented as two elements with 0xFF marker
    test_cases = [
        {
            'desc': 'Test 1: (1, 5, 7, (4, 6), 10)',
            'input': [0x0001, 0x0005, 0x0007, 0xFF04, 0xFF06, 0x000A],
