        },
        {
            'desc': 'Test 2: (2, 6, 8, (5, 7), 11)',
            'input': [0x0002, 0x0006, 0x0008, 0xFF05, 0xFF07, 0x000B],
            'input_len': 6,
            'expected': [2, 6, 8, 11]
        },
        {
            'desc': 'Test 3: (3, 7, 9, (6, 8), 12)',
            'input': [0x0003, 0x0007, 0x0009, 0xFF06, 0xFF08, 0x000C],
            'input_len': 6,
            'expected': [3, 7, 9, 12]
        },
        {
            'desc': 'Test 4: (3, 7, 9, (6, 8), (5,12), 12)',
