                    # Try packed access (assuming 16-bit values)
                    full_val = int(dut.output_data.value)
                    val = (full_val >> (i * DATA_WIDTH)) & ((1 << DATA_WIDTH) - 1)
                # Only consider lower 8 bits as per spec
                val = val & 0xFF
                out_data_list.append(val)

