async def test_median_two_sorted_lists(dut):
    # Setup clock
    cocotb.start_soon(Clock(dut.clk, CLK_NS, units='ns').start())

    # Reset
    await reset_dut(dut)

    # Test cases
    # Note: Python get_median sums m1+m2 and divides by 2.0
    # HDL needs to implement (m1+m2)/2 scaled to Q8.8
    test_cases = [
        ([1, 12, 15, 26, 38], [2, 13, 17, 30, 45], 5, 16.0),
        ([2, 4, 8, 9], [7, 13, 19, 28], 4, 8.5),
        ([3, 6, 14, 23, 36, 42], [2, 18, 27, 39, 49, 55], 6, 25.0)
    ]

    for i, (arr1, arr2, n, expected) in enumerate(test_cases):
        cocotb.log.info(f"Running Test Case {i+1}: n={n}, expected={expected}")

        # Initialize arrays with zeros
        # We attempt to access dut.arr1[i] which is standard for unpacked arrays in cocotb
        for k in range(ARRAY_SIZE):
            if hasattr(dut, 'arr1'):
                dut.arr1[k].value = 0
            elif hasattr(dut, f'arr1_{k}'):
                getattr(dut, f'arr1_{k}').value = 0

            if hasattr(dut, 'arr2'):
                dut.arr2[k].value = 0
            elif hasattr(dut, f'arr2_{k}'):
                getattr(dut, f'arr2_{k}').value = 0

        # Fill valid data
        try:
            for k, val in enumerate(arr1):
                if hasattr(dut, 'arr1'):
                    dut.arr1[k].value = clamp_to_width(val, DATA_WIDTH)
                else:
                    getattr(dut, f'arr1_{k}').value = clamp_to_width(val, DATA_WIDTH)
            for k, val in enumerate(arr2):
                if hasattr(dut, 'arr2'):
                    dut.arr2[k].value = clamp_to_width(val, DATA_WIDTH)
                else:
                    getattr(dut, f'arr2_{k}').value = clamp_to_width(val, DATA_WIDTH)
        except Exception as e:
            cocotb.log.error(f"Array assignment failed: {e}")
            raise TestFailure("Failed to assign input arrays.")

        # Drive n
        dut.n.value = n

        # Start
        dut.start.value = 1
        await RisingEdge(dut.clk)
        dut.start.value = 0

        # Wait for done
        await wait_for_done(dut)

        # Read result
        if not is_value_defined(dut.result.value):
             raise TestFailure("Result signal undefined")

        raw_result = int(dut.result.value)

        # Convert result back to float
        calculated = q8_8_to_float(raw_result)

        cocotb.log.info(f"Test {i+1}: Result (raw)={raw_result}, Calculated={calculated}, Expected={expected}")

        # Compare with tolerance for float
        # 0.01 tolerance accounts for Q8.8 precision (approx 0.0039)
        if abs(calculated - expected) > 0.02:
            raise TestFailure(f"Mismatch: Expected {expected}, Got {calculated}")

    cocotb.log.info("All tests passed!")

import cocotb
from cocotb.triggers import Timer, RisingEdge
from cocotb.clock import Clock
from cocotb.result import TestFailure
import random

# Helpers from template
DATA_WIDTH = 8
DP_WIDTH = 16
ARRAY_SIZE = 64
CLK_NS = 10
MAX_CYCLES = 200

Q8_8_SHIFT = 256  # 2^8 for Q8.8

# Helper functions
def is_value_defined(v):
    try:
        int(v)
        return True
    except ValueError:
        return False

def safe_int(v, default=0):
    try:
        return int(v)
    except ValueError:
        return default

def to_signed(val, bits):
    return val - (1 << bits) if val >= (1 << (bits-1)) else val

def from_signed(val, bits):
    return val + (1 << bits) if val < 0 else val

def has_signal(dut, name):
    try:
        getattr(dut, name)
        return True
    except AttributeError:
        return False

def clamp_to_width(v, bits):
    return min((1 << bits) - 1, max(0, v))

def clamp_signed(v, bits):
    max_val = (1 << (bits - 1)) - 1
    min_val = -(1 << (bits - 1))
    return min(max(v, min_val), max_val)

def pack_cost_array(cost_grid, N=8, bits=8):
    """Pack 2D cost array into single bit vector for Verilog input"""
    packed = 0
    for i in range(N):
        for j in range(N):
            cost = clamp_signed(cost_grid[i][j], bits)
            idx = i * N + j
            packed |= (from_signed(cost, bits) & ((1 << bits) - 1)) << (idx * bits)
    return packed

def compute_expected(cost_grid, N=8):
    """Compute expected average using Python DP"""
    dp = [[0] * N for _ in range(N)]
    dp[0][0] = cost_grid[0][0]

    # First row
    for j in range(1, N):
        dp[0][j] = dp[0][j-1] + cost_grid[0][j]

    # First column
    for i in range(1, N):
        dp[i][0] = dp[i-1][0] + cost_grid[i][0]

    # Rest of grid
    for i in range(1, N):
        for j in range(1, N):
            dp[i][j] = max(dp[i-1][j], dp[i][j-1]) + cost_grid[i][j]

    total_sum = dp[N-1][N-1]
    path_length = 2 * N - 1
    average = total_sum / path_length

    # Convert to Q8.8 format
    return int(average * Q8_8_SHIFT)

async def reset_dut(dut, cycles=2):
    dut.rst_n.value = 0
    if has_signal(dut, 'start'): dut.start.value = 0
    for _ in range(cycles):
        await RisingEdge(dut.clk)
    dut.rst_n.value = 1
    await RisingEdge(dut.clk)

async def wait_for_done(dut, max_cycles=200):
    for _ in range(max_cycles):
        await RisingEdge(dut.clk)
        if is_value_defined(dut.done.value) and int(dut.done.value) == 1:
            return True
    raise TestFailure(f"Timeout after {max_cycles} cycles")

