        cost_grid = [[0] * N for _ in range(N)]
        for i in range(3):
            for j in range(3):
                cost_grid[i][j] = small_grid[i][j]

        cocotb.log.info(f"Test {idx+1}: {name}")

        try:
            # Pack costs
            packed_costs = pack_cost_array(cost_grid, N, DATA_WIDTH)

            # Set inputs
            if has_signal(dut, 'cost'):
                dut.cost.value = packed_costs

            if is_seq:
