PI_Q16_16 = int(math.pi * (1 << 16))  # 0x3243F
INV_360_Q16_16 = int((1/360) * (1 << 16))  # 0x15E
MAX_ANGLE_FIXED = 360 * (1 << 16)  # 0x01680000

def is_value_defined(v):
    try:
        int(v)
        return True
    except ValueError:
        return False

def safe_int(v, default=0):
