    if a_q16_16 > MAX_ANGLE_FIXED:
        return None
    # area = (π * r^2 * a) / 360
    r = r_q16_16 / (1 << 16)
    a = a_q16_16 / (1 << 16)
    area = (math.pi * r * r) * (a / 360)
    return int(area * (1 << 16))

