                valid_vec = int(dut.result_valid.value)
                if (valid_vec >> i) & 1:
                    h = int(dut.result_hash.value) # Assuming vector or array
                    c = int(dut.result_count.value)
                    # This logic is tricky for vectors, assuming 4 outputs valid for now
